  function download(){const blob=new Blob([JSON.stringify({version:1,exportedAt:new Date().toISOString(),projects:saved},null,2)],{type:'application/json'});const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download='heynomus-watchlist.json';a.click();URL.revokeObjectURL(a.href);notify('Watchlist exported.');}
