  return <section className="compare-column"><button className="compare-remove icon-btn" onClick={remove} aria-label={'Remove '+slug}><X size={16}/></button>{loading?<Busy/>:error?<Failure error={error} retry={reload}/>:data&&<><a href={'/project/'+slug}><h2>{data.identity?.name||slug}</h2></a><span className="ticker">{data.identity?.symbol&&'$'+data.identity.symbol}</span><dl className="key-values compare-metrics"><div><dt>Build activity</dt><dd>{data.build?.activity?.label||label(data.build?.activityStatus)}</dd></div><div><dt>Last ship</dt><dd>{ago(data.build?.lastShippedAt)}</dd></div><div><dt>Build momentum</dt><dd>{num(data.build?.buildMomentum)} / 100</dd></div><div><dt>Research standing</dt><dd>{label(data.identity?.researchLevel)}</dd></div><div><dt>Calls measured</dt><dd>{num(data.usage?.calls)}</dd></div><div><dt>Days covered</dt><dd>{data.usage?.daysCovered??'—'} / {data.usage?.window?.days??'—'}</dd></div></dl>{data.summary?.lines?.map((l:Data)=><div className="compare-brief" key={l.dimension}><span className="eyebrow">{l.label} · {l.tag}</span><p>{l.text}</p><Out href={l.detailUrl}>Source<ArrowUpRight size={11}/></Out></div>)}<Provider data={data}/></>}</section>;
